import React from 'react'
import loading_gif from 'assets/icons/loading.gif'
const Loading = () => {
    return (
        <div className='fixed  transition-opacity ease-in-out delay-150 duration-300 top-0 left-0 w-full h-screen flex justify-center items-center bg-[rgba(0,0,0,.6)] z-50'>

            <div>
                <img src={loading_gif} alt='loading_gif' className='w-20' />
                <h4 className='text-[#fff] text-center'>please_wait ....</h4>
            </div>
        </div>
    )
}

export default Loading
